import path from 'node:path';
import {pathToFileURL,fileURLToPath} from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
process.env.CHROME_DEVTOOLS_MCP_NO_USAGE_STATISTICS = '1';
process.env.CHROME_DEVTOOLS_MCP_NO_UPDATE_CHECKS = '1';
process.env.CHROME_DEVTOOLS_MCP_NO_CONFIG_DISCOVERY = '1';
const executable = path.join(root,'node_modules/chrome-devtools-mcp/build/src/bin/chrome-devtools-mcp.js');
process.argv = [process.execPath, executable,
  '--headless', '--isolated',
  '--executable-path=C:/Program Files/Google/Chrome/Application/chrome.exe',
  '--no-usage-statistics', '--no-performance-crux',
  '--redact-network-headers', '--viewport=1365x900',
  '--no-category-emulation', '--no-category-memory',
];
await import(pathToFileURL(executable).href);
